'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { MODELS_DURING_FAULT, PRODUCT_NAME, serviceOf, SERVICES } from './data';
import { Incidents } from './incidents';
import { LatencyChart } from './latency-chart';
import { ServiceList } from './services';
import {
  CONFIRM_MS,
  hasIncidentToday,
  INITIAL,
  isFaultOpen,
  isSlowNow,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type Reading,
  type StatusState,
} from './session';
import { Subscribe } from './subscribe';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function headlineOf(isDegraded: boolean) {
  if (isDegraded) {
    return 'Model endpoints are slower than usual';
  }
  return 'All systems operational';
}

function orbToneOf(isDegraded: boolean) {
  if (isDegraded) {
    return 'warning';
  }
  return 'success';
}

/** While the fault slows the model endpoints, their chart shows the end of both lines lifted. */
function chartServiceOf(state: StatusState) {
  const isModels = state.selected === 'models';
  if (isModels && isSlowNow(state)) {
    return MODELS_DURING_FAULT;
  }
  return serviceOf(state.selected);
}

/** The day the demonstration reads leaves with the demonstration. */
function demoReadingOf(isDemonstrating: boolean, reading: Reading | null) {
  if (isDemonstrating) {
    return reading;
  }
  return null;
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

export default function AgentOps03() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const isDegraded = isFaultOpen(state);
  const headline = headlineOf(isDegraded);
  const chartService = chartServiceOf(state);
  const demoReading = demoReadingOf(isAutoplaying, state.reading);
  const message = spokenUnless(isAutoplaying, headline);
  const canReplay = isFinished && !isAutoplaying;

  function subscribe() {
    act({ type: 'subscribe' });
    schedule(() => act({ type: 'subscribed' }), CONFIRM_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-5 p-4 @3xl:gap-6 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-4 gap-y-3'>
            <StatusOrb tone={orbToneOf(isDegraded)} />
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='text-xl font-semibold text-balance'>
                <Swap swapKey={headline}>{headline}</Swap>
              </h1>
              <p className='text-muted-foreground text-xs'>
                {PRODUCT_NAME} status · {SERVICES.length} services ·
                Illustrative figures
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the incident'
            />
          </header>

          <div className='flex flex-col gap-4 @4xl:grid @4xl:grid-cols-2 @4xl:items-start @4xl:gap-5'>
            <div className='min-w-0 @4xl:order-2'>
              <LatencyChart service={chartService} />
            </div>
            <div className='min-w-0 @4xl:order-1'>
              <ServiceList
                selected={state.selected}
                hasFaultToday={hasIncidentToday(state)}
                isFaultOpen={isDegraded}
                demoReading={demoReading}
                pressed={pressed}
                onSelect={(id) => act({ type: 'selected', id })}
              />
            </div>
          </div>

          <div className='flex flex-col gap-5 @4xl:grid @4xl:grid-cols-[minmax(0,1fr)_22rem] @4xl:items-start @4xl:gap-8'>
            <Incidents liveUpdatesOut={state.updatesOut} />
            <Subscribe
              email={state.email}
              subscription={state.subscription}
              isPressed={pressed === 'subscribe'}
              onEmailChange={(text) => act({ type: 'typed', text })}
              onSubscribe={subscribe}
              onUnsubscribe={() => act({ type: 'unsubscribed' })}
            />
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  dateLabelOf,
  DAY_COUNT,
  dayEventOf,
  FAULT_MINUTES,
  SERVICES,
  TODAY,
  uptimeOf,
  type DayEvent,
  type DayStatus,
  type Service,
  type ServiceId,
} from './data';

/** Phones show the last 45 days: 90 cells in 343 pixels are too thin to read or to touch. */
const PHONE_DAYS = 45;

const FIRST_PHONE_DAY = DAY_COUNT - PHONE_DAYS;

const DAYS = Array.from({ length: DAY_COUNT }, (_, day) => day);

const DAY_WORD: Record<DayStatus, string> = {
  ok: 'No incident',
  degraded: 'Slower than usual',
  outage: 'Down',
};

const DAY_TONE: Record<DayStatus, string> = {
  ok: 'bg-success/50',
  degraded: 'bg-warning',
  outage: 'bg-destructive',
};

const STATE_WORDS = ['Operational', 'Degraded'];

const UPTIME_FORMAT = new Intl.NumberFormat('en-US', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

/** The bubble follows the day it reads and stops at both ends of the bar, so it never leaves the block. */
const BUBBLE_LEFT =
  'clamp(4.75rem, calc((var(--day) - var(--first-day) + 0.5) / var(--day-count) * 100%), calc(100% - 4.75rem))';

type BubbleStyle = React.CSSProperties & { '--day': number };

function minutesOf(event: DayEvent) {
  if (event.status === 'ok') {
    return 'Every request answered in time';
  }
  if (event.minutes === 1) {
    return '1 minute affected';
  }
  return `${event.minutes} minutes affected`;
}

function stateWordOf(isDegraded: boolean) {
  if (isDegraded) {
    return 'Degraded';
  }
  return 'Operational';
}

function stateToneOf(isDegraded: boolean) {
  if (isDegraded) {
    return 'text-warning-foreground';
  }
  return 'text-muted-foreground';
}

function dotToneOf(isDegraded: boolean) {
  if (isDegraded) {
    return 'bg-warning';
  }
  return 'bg-success';
}

/** The picked service is tinted as a whole, so its button only answers the pointer when it is not picked. */
function rowToneOf(isSelected: boolean) {
  if (isSelected) {
    return undefined;
  }
  return 'hover:bg-foreground/[0.04]';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.985] bg-foreground/[0.07]';
  }
  return undefined;
}

function cellLiftOf(isRead: boolean) {
  if (isRead) {
    return '-translate-y-0.5 opacity-100';
  }
  return 'opacity-75';
}

function dayOfTarget(target: EventTarget) {
  if (!(target instanceof HTMLElement)) {
    return null;
  }
  const value = target.dataset.day;
  if (value === undefined) {
    return null;
  }
  return Number(value);
}

function firstDayOf(bar: HTMLElement) {
  const value = getComputedStyle(bar).getPropertyValue('--first-day');
  return Number(value);
}

function steppedDayOf(key: string, current: number, firstDay: number) {
  if (key === 'ArrowRight') {
    return Math.min(current + 1, TODAY);
  }
  if (key === 'ArrowLeft') {
    return Math.max(current - 1, firstDay);
  }
  if (key === 'Home') {
    return firstDay;
  }
  if (key === 'End') {
    return TODAY;
  }
  return null;
}

type UptimeBarProps = {
  service: Service;
  todayEvent: DayEvent | null;
  /** The day the demonstration reads, shown while no pointer and no key reads another. */
  demoDay: number | null;
};

function UptimeBar({ service, todayEvent, demoDay }: UptimeBarProps) {
  const [pointerDay, setPointerDay] = useState<number | null>(null);
  const [keyDay, setKeyDay] = useState<number | null>(null);
  const [lastDay, setLastDay] = useState(TODAY);
  const activeDay = pointerDay ?? keyDay ?? demoDay;
  const isReading = activeDay !== null;
  if (activeDay !== null && activeDay !== lastDay) {
    setLastDay(activeDay);
  }

  function eventOf(day: number) {
    const isToday = day === TODAY;
    if (isToday && todayEvent) {
      return todayEvent;
    }
    return dayEventOf(service.id, day);
  }

  const shownDay = activeDay ?? lastDay;
  const shownEvent = eventOf(shownDay);
  const shownDate = dateLabelOf(shownDay);
  const shownWord = DAY_WORD[shownEvent.status];
  const shownMinutes = minutesOf(shownEvent);
  const bubbleStyle: BubbleStyle = { left: BUBBLE_LEFT, '--day': shownDay };
  const isReadingByKeys = keyDay !== null;
  const spokenReading = `${shownDate}: ${shownWord}. ${shownMinutes}`;

  function point(event: React.PointerEvent<HTMLDivElement>) {
    const day = dayOfTarget(event.target);
    if (day !== null) {
      setPointerDay(day);
    }
  }

  function leave(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'mouse') {
      setPointerDay(null);
    }
  }

  function focus(event: React.FocusEvent<HTMLDivElement>) {
    const isKeyboardFocus = event.currentTarget.matches(':focus-visible');
    if (isKeyboardFocus) {
      setKeyDay(lastDay);
    }
  }

  function blur() {
    setKeyDay(null);
    setPointerDay(null);
  }

  function step(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      setKeyDay(null);
      return;
    }
    const firstDay = firstDayOf(event.currentTarget);
    const current = keyDay ?? lastDay;
    const next = steppedDayOf(event.key, current, firstDay);
    if (next === null) {
      return;
    }
    event.preventDefault();
    setPointerDay(null);
    setKeyDay(next);
  }

  return (
    <div className='relative [--day-count:45] [--first-day:45] @md:[--day-count:90] @md:[--first-day:0]'>
      <div
        role='group'
        tabIndex={0}
        aria-label={`Uptime of ${service.name}, day by day. Use the arrow keys to read each day.`}
        onPointerMove={point}
        onPointerDown={point}
        onPointerLeave={leave}
        onFocus={focus}
        onBlur={blur}
        onKeyDown={step}
        className='focus-visible:ring-ring/25 flex h-7 touch-pan-y items-stretch gap-px rounded-sm outline-none focus-visible:ring-[3px]'
      >
        {DAYS.map((day) => {
          const event = eventOf(day);
          const isPhoneDay = day >= FIRST_PHONE_DAY;
          const isRead = isReading && day === activeDay;
          return (
            <span
              key={day}
              data-day={day}
              className={cn(
                'min-w-0 flex-1 rounded-[2px] transition-[translate,opacity,background-color] duration-100',
                DAY_TONE[event.status],
                cellLiftOf(isRead),
                !isPhoneDay && 'hidden @md:block'
              )}
            />
          );
        })}
      </div>
      <div
        aria-hidden='true'
        style={bubbleStyle}
        className='pointer-events-none absolute bottom-full z-10 mb-1.5 w-0'
      >
        <div
          className={cn(
            'surface-raised flex w-36 -translate-x-1/2 flex-col gap-0.5 rounded-lg px-2.5 py-1.5 text-xs',
            'origin-bottom transition-[opacity,scale] duration-[125ms] ease-(--ease-out-strong)',
            !isReading && 'scale-[0.97] opacity-0'
          )}
        >
          <span className='text-muted-foreground tabular-nums'>
            {shownDate}
          </span>
          <span className='font-medium'>{shownWord}</span>
          <span className='text-muted-foreground tabular-nums'>
            {shownMinutes}
          </span>
        </div>
      </div>
      <span aria-live='polite' className='sr-only'>
        {isReadingByKeys && spokenReading}
      </span>
    </div>
  );
}

type ServiceRowProps = {
  service: Service;
  isSelected: boolean;
  isDegraded: boolean;
  isPressed: boolean;
  todayEvent: DayEvent | null;
  demoDay: number | null;
  onSelect: (id: ServiceId) => void;
};

function ServiceRow({
  service,
  isSelected,
  isDegraded,
  isPressed,
  todayEvent,
  demoDay,
  onSelect,
}: ServiceRowProps) {
  const lostToday = todayEvent?.minutes ?? 0;
  const uptime = uptimeOf(service.id, lostToday);
  const uptimeText = UPTIME_FORMAT.format(uptime);

  return (
    <li
      className={cn(
        'flex flex-col gap-2 rounded-lg px-2 pt-1 pb-2.5 transition-colors duration-200',
        isSelected && 'bg-foreground/[0.03]'
      )}
    >
      <button
        type='button'
        aria-pressed={isSelected}
        onClick={() => onSelect(service.id)}
        className={cn(
          'focus-visible:ring-ring/25 -mx-1 flex min-h-11 cursor-pointer items-center gap-3 rounded-md px-1 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px]',
          rowToneOf(isSelected),
          pressedQuietOf(isPressed)
        )}
      >
        <span
          aria-hidden='true'
          className={cn(
            'size-2 shrink-0 rounded-full transition-colors duration-300',
            dotToneOf(isDegraded)
          )}
        />
        <span className='flex min-w-0 flex-1 flex-col leading-tight'>
          <span className='truncate text-[13px] font-medium'>
            {service.name}
          </span>
          <span
            className={cn(
              'text-xs transition-colors duration-300',
              stateToneOf(isDegraded)
            )}
          >
            <WordRoll text={stateWordOf(isDegraded)} labels={STATE_WORDS} />
          </span>
        </span>
        <span className='flex shrink-0 flex-col items-end leading-tight'>
          <span className='text-[13px] font-medium tabular-nums'>
            {uptimeText}%
          </span>
          <span className='text-muted-foreground text-xs'>
            uptime over {DAY_COUNT} days
          </span>
        </span>
      </button>
      <UptimeBar service={service} todayEvent={todayEvent} demoDay={demoDay} />
      <div
        aria-hidden='true'
        className='text-muted-foreground flex justify-between text-[11px]'
      >
        <span className='@md:hidden'>{PHONE_DAYS} days ago</span>
        <span className='hidden @md:inline'>{DAY_COUNT} days ago</span>
        <span>Today</span>
      </div>
    </li>
  );
}

type ServiceListProps = {
  selected: ServiceId;
  hasFaultToday: boolean;
  isFaultOpen: boolean;
  demoReading: { serviceId: ServiceId; day: number } | null;
  pressed: string | null;
  onSelect: (id: ServiceId) => void;
};

const FAULT_TODAY: DayEvent = { status: 'degraded', minutes: FAULT_MINUTES };

function todayEventOf(serviceId: ServiceId, hasFaultToday: boolean) {
  const isHit = serviceId === 'models' && hasFaultToday;
  if (isHit) {
    return FAULT_TODAY;
  }
  return null;
}

function demoDayOf(
  serviceId: ServiceId,
  reading: { serviceId: ServiceId; day: number } | null
) {
  if (reading?.serviceId === serviceId) {
    return reading.day;
  }
  return null;
}

export function ServiceList({
  selected,
  hasFaultToday,
  isFaultOpen,
  demoReading,
  pressed,
  onSelect,
}: ServiceListProps) {
  return (
    <section
      aria-label='Services'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] @container rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <ul className='flex flex-col gap-0.5'>
        {SERVICES.map((service) => {
          const isModels = service.id === 'models';
          return (
            <ServiceRow
              key={service.id}
              service={service}
              isSelected={selected === service.id}
              isDegraded={isModels && isFaultOpen}
              isPressed={pressed === `service-${service.id}`}
              todayEvent={todayEventOf(service.id, hasFaultToday)}
              demoDay={demoDayOf(service.id, demoReading)}
              onSelect={onSelect}
            />
          );
        })}
      </ul>
    </section>
  );
}

'use client';

import { motion, useReducedMotion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { seriesColorOf, type SeriesSlot } from '@/registry/ndeko/lib/agent-run';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import type { Service } from './data';

const VIEW_WIDTH = 1000;

const PLOT_HEIGHT = 168;

const MOVE: Transition = { duration: 0.45, ease: [0.77, 0, 0.175, 1] };

const INSTANT: Transition = { duration: 0 };

const P50_SERIES: SeriesSlot = 1;

const P95_SERIES: SeriesSlot = 2;

const TICK_SHARES = [1, 0.5, 0];

function moveOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MOVE;
}

function yOf(valueMs: number, topMs: number) {
  const share = valueMs / topMs;
  const bounded = Math.min(1, Math.max(0, share));
  return PLOT_HEIGHT - bounded * PLOT_HEIGHT;
}

function commandOf(
  valueMs: number,
  hour: number,
  count: number,
  topMs: number
) {
  const lastHour = count - 1;
  const x = (hour / lastHour) * VIEW_WIDTH;
  const y = yOf(valueMs, topMs);
  const point = `${x.toFixed(1)} ${y.toFixed(1)}`;
  if (hour === 0) {
    return `M${point}`;
  }
  return `L${point}`;
}

function pathOf(values: number[], topMs: number) {
  const commands = values.map((valueMs, hour) =>
    commandOf(valueMs, hour, values.length, topMs)
  );
  return commands.join(' ');
}

/** 80 ms, 900 ms, 2.4 s. */
function formatMs(valueMs: number) {
  if (valueMs < 1000) {
    return `${valueMs} ms`;
  }
  const seconds = valueMs / 1000;
  return `${seconds.toFixed(1)} s`;
}

function hourLabelOf(hour: number, count: number) {
  const hoursAgo = count - 1 - hour;
  if (hoursAgo === 0) {
    return 'Now';
  }
  return `${hoursAgo} h ago`;
}

function p95ToneOf(isOverTarget: boolean) {
  if (isOverTarget) {
    return 'text-warning-foreground';
  }
  return 'text-foreground';
}

type FigureProps = {
  label: string;
  series?: SeriesSlot;
  valueMs: number;
  className?: string;
};

function Figure({ label, series, valueMs, className }: FigureProps) {
  return (
    <div className='flex min-w-0 flex-col gap-0.5'>
      <dt className='text-muted-foreground flex items-center gap-1.5 text-xs'>
        {series !== undefined && (
          <span
            aria-hidden='true'
            style={{ backgroundColor: seriesColorOf(series) }}
            className='size-2 shrink-0 rounded-full'
          />
        )}
        {label}
      </dt>
      <dd
        className={cn(
          'text-lg leading-7 font-semibold transition-colors duration-300 @md:text-xl',
          className
        )}
      >
        <MotionNumber value={valueMs} suffix=' ms' />
      </dd>
    </div>
  );
}

type LatencyChartProps = {
  service: Service;
};

export function LatencyChart({ service }: LatencyChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const move = moveOf(shouldReduceMotion);
  const hourCount = service.p50.length;
  const lastHour = hourCount - 1;
  const p50Now = service.p50[lastHour];
  const p95Now = service.p95[lastHour];
  const p50Path = pathOf(service.p50, service.topMs);
  const p95Path = pathOf(service.p95, service.topMs);
  const targetY = yOf(service.targetMs, service.topMs);
  const targetStyle = { transform: `translateY(${targetY}px)` };
  const plotStyle = { height: PLOT_HEIGHT };
  const isOverTarget = p95Now > service.targetMs;
  const title = `${service.name}: response time over 24 hours`;

  return (
    <section
      aria-label='Response time'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <header className='flex items-start justify-between gap-3'>
        <div className='flex min-w-0 flex-col gap-0.5'>
          <h2 className='text-sm font-medium'>
            <Swap swapKey={service.id}>{service.name}</Swap>
          </h2>
          <p className='text-muted-foreground text-xs'>
            <Swap swapKey={service.id}>{service.measure}, last 24 hours</Swap>
          </p>
        </div>
        <Badge variant='secondary'>Illustrative</Badge>
      </header>

      <dl className='grid grid-cols-3 gap-3'>
        <Figure label='p50 now' series={P50_SERIES} valueMs={p50Now} />
        <Figure
          label='p95 now'
          series={P95_SERIES}
          valueMs={p95Now}
          className={p95ToneOf(isOverTarget)}
        />
        <Figure label='Target' valueMs={service.targetMs} />
      </dl>

      <div className='grid grid-cols-[2.75rem_minmax(0,1fr)]'>
        <div aria-hidden='true' className='relative' style={plotStyle}>
          {TICK_SHARES.map((share) => {
            const tickMs = service.topMs * share;
            const top = yOf(tickMs, service.topMs);
            const label = formatMs(tickMs);
            return (
              <span
                key={share}
                className='text-muted-foreground absolute right-2.5 -translate-y-1/2 text-[11px] tabular-nums'
                style={{ top }}
              >
                <Swap swapKey={label}>{label}</Swap>
              </span>
            );
          })}
        </div>
        <div aria-hidden='true' className='relative' style={plotStyle}>
          <svg
            viewBox={`0 0 ${VIEW_WIDTH} ${PLOT_HEIGHT}`}
            preserveAspectRatio='none'
            className='absolute inset-0 size-full overflow-visible'
          >
            {TICK_SHARES.map((share) => {
              const y = PLOT_HEIGHT - share * PLOT_HEIGHT;
              return (
                <line
                  key={share}
                  x1={0}
                  x2={VIEW_WIDTH}
                  y1={y}
                  y2={y}
                  strokeWidth={1}
                  vectorEffect='non-scaling-stroke'
                  className='stroke-border'
                />
              );
            })}
            <motion.path
              initial={false}
              animate={{ d: p95Path }}
              transition={move}
              fill='none'
              strokeWidth={2}
              strokeLinecap='round'
              strokeLinejoin='round'
              vectorEffect='non-scaling-stroke'
              style={{ stroke: seriesColorOf(P95_SERIES) }}
            />
            <motion.path
              initial={false}
              animate={{ d: p50Path }}
              transition={move}
              fill='none'
              strokeWidth={2}
              strokeLinecap='round'
              strokeLinejoin='round'
              vectorEffect='non-scaling-stroke'
              style={{ stroke: seriesColorOf(P50_SERIES) }}
            />
          </svg>
          <div
            style={targetStyle}
            className='pointer-events-none absolute inset-x-0 top-0 transition-transform duration-[450ms] ease-(--ease-in-out-strong)'
          >
            <span className='bg-foreground/35 absolute inset-x-0 top-0 h-(--hairline)' />
            <span className='text-muted-foreground absolute end-0 -top-4 text-[11px] leading-4'>
              Target
            </span>
          </div>
